package pqc_test

// Known-answer vectors for the hybrid cryptography of Communities (Go reference ↔ app).
//
// testdata/pq-vectors.json is generated by the Go reference from fixed secrets and is checked by the
// app (Kotlin on top of the Rust core) and by the Rust core (core/src/devlink/tests.rs,
// comm_vault_root_matches_communities_vectors).
//
// This test needs nothing but package pqc and the standard library. It checks, against the file:
//   - every member's Ed25519, ML-DSA-65 and X25519 + ML-KEM-1024 keys derive from its two secrets;
//   - ML-DSA-65 and Ed25519 sign deterministically, so the request, rekey and filter-bundle
//     signatures are recomputed and compared byte for byte, and must verify;
//   - the ML-KEM-1024 half of each sealed box decapsulates to the recorded shared secret;
//   - a private-channel post decrypts under its post key and carries both author signatures;
//   - the membership vault keys derive from the X25519 secret and the ML-KEM seed.

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"io"
	"os"
	"testing"

	"github.com/cloudflare/circl/kem/mlkem/mlkem1024"
	"golang.org/x/crypto/hkdf"

	"github.com/UmberaAPP/UMBERA/communities/pqc"
)

const vecPath = "testdata/pq-vectors.json"

// Domain strings of the private-channel post format (same values as in CommCrypto.kt).
const (
	postAEADInfo   = "umbera-comm-post-v1"
	postSigDomain  = "UMBERA-COMM-POSTSIG-v2\n"
	privateVersion = 2
)

type vMember struct {
	Seed      string `json:"seed"`
	EncPriv   string `json:"enc_priv"`
	EdPub     string `json:"ed_pub"`
	MlDsaSeed string `json:"mldsa_seed"`
	MlDsaPub  string `json:"mldsa_pub"`
	MlKemSeed string `json:"mlkem_seed"`
	EncPub    string `json:"enc_pub"`
}

type vRequest struct {
	SignedString string `json:"signed_string"`
	EdSig        string `json:"ed_sig"`
	PqSig        string `json:"pq_sig"`
}

type vSeal struct {
	KemSS  string `json:"kem_ss"`
	Box    string `json:"box"`
	ToUser int    `json:"to"`
}

type vPost struct {
	Author    int    `json:"author"`
	ChannelID string `json:"channel_id"`
	Epoch     int    `json:"epoch"`
	JSON      string `json:"json"`
	PostKey   string `json:"post_key"`
	BodyEnc   string `json:"body_enc"`
}

type vVault struct {
	X25519Priv string `json:"x25519_priv"`
	MlKemSeed  string `json:"mlkem_seed"`
	ID         string `json:"id"`
	AuthSeed   string `json:"auth_seed"`
	EncKey     string `json:"enc_key"`
}

type vRekey struct {
	Message string `json:"message"`
	EdSig   string `json:"ed_sig"`
	PqSig   string `json:"pq_sig"`
}

type vBundle struct {
	EdPub string `json:"ed_pub"`
	PqPub string `json:"mldsa_pub"`
	Msg   string `json:"msg"`
	EdSig string `json:"ed_sig"`
	PqSig string `json:"pq_sig"`
}

type vectors struct {
	Members  []vMember `json:"members"`
	Request  vRequest  `json:"request"`
	Seal     vSeal     `json:"seal"`
	Envelope vSeal     `json:"channel_key_envelope"`
	Post     vPost     `json:"post"`
	Vault    vVault    `json:"vault"`
	Rekey    vRekey    `json:"rekey"`
	Bundle   vBundle   `json:"filter_bundle"`
}

func unhex(t testing.TB, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

func load(t testing.TB) (vectors, []*pqc.Member) {
	t.Helper()
	raw, err := os.ReadFile(vecPath)
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if len(v.Members) < 3 {
		t.Fatalf("expected 3 members, got %d", len(v.Members))
	}
	var ms []*pqc.Member
	for i, vm := range v.Members {
		seed := unhex(t, vm.Seed)
		m, err := pqc.DeriveMember(seed, unhex(t, vm.EncPriv))
		if err != nil {
			t.Fatal(err)
		}
		for name, ok := range map[string]bool{
			"ed_pub":     bytes.Equal(m.EdPub, unhex(t, vm.EdPub)),
			"mldsa_seed": bytes.Equal(pqc.DSASeed(seed), unhex(t, vm.MlDsaSeed)),
			"mldsa_pub":  bytes.Equal(m.DSAPub, unhex(t, vm.MlDsaPub)),
			"mlkem_seed": bytes.Equal(pqc.KEMSeed(seed), unhex(t, vm.MlKemSeed)),
			"enc_pub":    bytes.Equal(m.Enc.Pub, unhex(t, vm.EncPub)),
		} {
			if !ok {
				t.Fatalf("member %d: %s differs from the vector", i, name)
			}
		}
		ms = append(ms, m)
	}
	return v, ms
}

// signedBy recomputes a deterministic hybrid signature and compares it with the vector.
func signedBy(t testing.TB, m *pqc.Member, msg []byte, edHex, pqHex, what string) {
	t.Helper()
	ed, pq := m.Sign(msg)
	if !bytes.Equal(ed, unhex(t, edHex)) || !bytes.Equal(pq, unhex(t, pqHex)) {
		t.Fatalf("%s: signature differs from the vector", what)
	}
	if !pqc.Verify(m.EdPub, m.DSAPub, msg, ed, pq) {
		t.Fatalf("%s: signature does not verify", what)
	}
}

func vaultKeys(xpriv, kemSeed []byte) (id, auth, enc []byte) {
	ikm := append(append([]byte{}, xpriv...), kemSeed...)
	d := func(info string) []byte {
		out := make([]byte, 32)
		_, _ = io.ReadFull(hkdf.New(sha256.New, ikm, []byte("umbera-comm-vault-v2"), []byte(info)), out)
		return out
	}
	return d("vault-id"), d("vault-auth"), d("vault-key")
}

func TestVectorsFile(t *testing.T) {
	v, ms := load(t)

	signedBy(t, ms[0], []byte(v.Request.SignedString), v.Request.EdSig, v.Request.PqSig, "request")
	signedBy(t, ms[1], unhex(t, v.Rekey.Message), v.Rekey.EdSig, v.Rekey.PqSig, "rekey")
	if !pqc.Verify(unhex(t, v.Bundle.EdPub), unhex(t, v.Bundle.PqPub), []byte(v.Bundle.Msg), unhex(t, v.Bundle.EdSig), unhex(t, v.Bundle.PqSig)) {
		t.Fatal("filter bundle: signature does not verify")
	}

	// Sealed boxes: version(1) ‖ ephemeral X25519(32) ‖ ML-KEM-1024 ciphertext ‖ ...
	for name, s := range map[string]vSeal{"seal": v.Seal, "channel_key_envelope": v.Envelope} {
		box := unhex(t, s.Box)
		if len(box) < 33+pqc.KEMCtSize {
			t.Fatalf("%s: box too short", name)
		}
		ss := make([]byte, mlkem1024.SharedKeySize)
		ms[s.ToUser].Enc.KEM.DecapsulateTo(ss, box[33:33+pqc.KEMCtSize])
		if !bytes.Equal(ss, unhex(t, s.KemSS)) {
			t.Fatalf("%s: ML-KEM-1024 shared secret differs from the vector", name)
		}
	}

	// Private-channel post: version(1) ‖ salt(16) ‖ iv(12) ‖ AES-256-GCM(ed25519 ‖ ML-DSA-65 ‖ json).
	p := v.Post
	enc, key := unhex(t, p.BodyEnc), unhex(t, p.PostKey)
	if len(enc) < 1+16+12+16 || enc[0] != privateVersion {
		t.Fatal("post: bad header")
	}
	ch := unhex(t, stripDashes(p.ChannelID))
	aad := append([]byte(postAEADInfo), ch...)
	var e [4]byte
	binary.BigEndian.PutUint32(e[:], uint32(p.Epoch))
	aad = append(aad, e[:]...)
	blk, err := aes.NewCipher(key)
	if err != nil {
		t.Fatal(err)
	}
	aead, err := cipher.NewGCM(blk)
	if err != nil {
		t.Fatal(err)
	}
	pt, err := aead.Open(nil, enc[17:29], enc[29:], aad)
	if err != nil {
		t.Fatalf("post: %v", err)
	}
	if len(pt) < pqc.HybridSigSize {
		t.Fatal("post: short plaintext")
	}
	sig, js := pt[:pqc.HybridSigSize], pt[pqc.HybridSigSize:]
	if string(js) != p.JSON {
		t.Fatal("post: body differs from the vector")
	}
	a := ms[p.Author]
	msg := append([]byte(postSigDomain+p.ChannelID+"\n"), js...)
	if !pqc.VerifyConcat(a.EdPub, a.DSAPub, msg, sig) {
		t.Fatal("post: author signature does not verify")
	}
	if !bytes.Equal(sig, a.SignConcat(msg)) {
		t.Fatal("post: author signature differs from a fresh deterministic signature")
	}

	id, au, ek := vaultKeys(unhex(t, v.Vault.X25519Priv), unhex(t, v.Vault.MlKemSeed))
	if hex.EncodeToString(id) != v.Vault.ID || hex.EncodeToString(au) != v.Vault.AuthSeed || hex.EncodeToString(ek) != v.Vault.EncKey {
		t.Fatal("vault keys differ from the vector")
	}
}

func stripDashes(s string) string {
	return string(bytes.ReplaceAll([]byte(s), []byte("-"), nil))
}

// Properties of the hybrid that do not depend on the app.
func TestHybridNegatives(t *testing.T) {
	_, ms := load(t)
	a, b := ms[0], ms[1]
	msg := []byte("m")
	ed, pq := a.Sign(msg)
	if !pqc.Verify(a.EdPub, a.DSAPub, msg, ed, pq) {
		t.Fatal("valid signature rejected")
	}
	edB, pqB := b.Sign(msg)
	for name, ok := range map[string]bool{
		"ed from other":   pqc.Verify(a.EdPub, a.DSAPub, msg, edB, pq),
		"pq from other":   pqc.Verify(a.EdPub, a.DSAPub, msg, ed, pqB),
		"pq key of other": pqc.Verify(a.EdPub, b.DSAPub, msg, ed, pq),
		"short pq":        pqc.Verify(a.EdPub, a.DSAPub, msg, ed, pq[:100]),
		"other msg":       pqc.Verify(a.EdPub, a.DSAPub, []byte("n"), ed, pq),
		"concat, ed only": pqc.VerifyConcat(a.EdPub, a.DSAPub, msg, ed),
	} {
		if ok {
			t.Fatalf("%s accepted", name)
		}
	}
	// A recipient key with only the X25519 half (32 bytes) is not a valid encryption key.
	if pqc.ValidEncPub(b.Enc.Pub[:32]) {
		t.Fatal("x25519-only recipient key accepted")
	}
	if !pqc.ValidEncPub(b.Enc.Pub) {
		t.Fatal("valid recipient key rejected")
	}
	junk := append([]byte{}, b.Enc.Pub...)
	for i := 32; i < len(junk); i++ {
		junk[i] = 0xff // coefficients >= q: not an ML-KEM public key
	}
	if pqc.ValidEncPub(junk) {
		t.Fatal("malformed ML-KEM key accepted")
	}
}
